from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.active_slot = 1

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if data.Splits.ContainsKey(self.spy):
            split = data.Splits[self.spy]
            if split.Type == SplitType.SplitOccurred and self.strategy_a_shares > 0:
                self.strategy_a_shares = int(
                    round(self.strategy_a_shares * float(split.SplitFactor))
                )

        if data.Splits.ContainsKey(self.aapl):
            split = data.Splits[self.aapl]
            if split.Type == SplitType.SplitOccurred and self.strategy_b_shares > 0:
                self.strategy_b_shares = int(
                    round(self.strategy_b_shares * float(split.SplitFactor))
                )

        current_spy_sma = None
        if spy_bar is not None:
            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close

        if self.IsWarmingUp:
            return

        required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        if any(not data.Bars.ContainsKey(symbol) for symbol in required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if (
            previous_spy_close is None
            or previous_spy_sma is None
            or current_spy_sma is None
            or self.previous_aapl_close is None
        ):
            return

        current_spy_close = float(spy_bar.Close)

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and current_spy_close > current_spy_sma
        )

        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and current_spy_close < current_spy_sma
        )

        aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60
        aapl_red_for_three_days = self.aapl_red_streak >= 3

        if self.active_slot == 1 and self.strategy_a_shares > 0:
            if spy_crosses_below:
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_shares,
                    tag="Strategy A sell"
                )
                self.strategy_a_shares = 0
                self.active_slot = 2

        elif self.active_slot == 2 and self.strategy_b_shares > 0:
            if aapl_rsi_above_60:
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_shares,
                    tag="Strategy B sell"
                )
                self.strategy_b_shares = 0
                self.active_slot = 1

        if self.active_slot == 1 and self.strategy_a_shares == 0:
            if spy_crosses_above:
                shares = int(
                    (float(self.Portfolio.TotalPortfolioValue) * 0.40)
                    / current_spy_close
                )

                if shares > 0:
                    self.MarketOrder(
                        self.spy,
                        shares,
                        tag="Strategy A buy"
                    )
                    self.strategy_a_shares = shares

        elif self.active_slot == 2 and self.strategy_b_shares == 0:
            available_cash = float(self.Portfolio.Cash)

            if aapl_red_for_three_days and available_cash >= 20000:
                shares = int(20000 / float(aapl_bar.Close))

                if shares > 0:
                    self.MarketOrder(
                        self.aapl,
                        shares,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_shares = shares

